"""Dynamic programming exercises."""


def lcs_length(a, b):
    """Length of the longest common subsequence of strings a and b."""
    # Ensure proper DP table size with an extra row and column for the empty prefix.
    m, n = len(a), len(b)
    # Table dimensions (m+1) x (n+1) initialized to 0.
    table = [[0] * (n + 1) for _ in range(m + 1)]
    # Fill the table using the standard LCS recurrence.
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                table[i][j] = table[i - 1][j - 1] + 1
            else:
                table[i][j] = max(table[i - 1][j], table[i][j - 1])
    # The result is in the bottom‑right cell.
    return table[m][n]


def edit_distance(a, b):
    """Minimum number of single-character inserts, deletes, or substitutions turning a into b."""
    m, n = len(a), len(b)
    # DP matrix sized (m+1) x (n+1).
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    # Initialize first column (deletions) and first row (insertions).
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    # Compute distances.
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,      # deletion
                dp[i][j - 1] + 1,      # insertion
                dp[i - 1][j - 1] + cost  # substitution
            )
    return dp[m][n]


def min_coins(coins, amount):
    """Fewest coins adding up to amount, with an unlimited supply of each denomination.

    Returns 0 for amount 0, and -1 if the amount cannot be made.
    """
    # DP array where best[v] is the minimum coins needed for amount v.
    best = [0] + [float("inf")] * amount
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value:
                best[value] = min(best[value], best[value - coin] + 1)
    result = best[amount]
    return -1 if result == float("inf") else result
